// BroWorld — карта Земли 1000×500 (равнопромежуточная проекция, долгота -169…191, широта 84…-80).
// Сгенерирована скриптом из данных Natural Earth 1:50m (суша, озёра; public domain) и рельефа NASA Visible Earth / GEBCO.
// Формат: RLE varint, токен = (длина-1)*80 + значение; значение = класс*16 + (тень+8).
// Классы: 0 океан, 1 озеро, 2 равнина (<300 м), 3 возвышенность (<1500 м), 4 горы.
export const MAP_W = 1000, MAP_H = 500;
export const LON0 = -169.0, LAT0 = 84.0, DLON = 0.36, DLAT = 0.328;
export const LAND_TILES = 154243;
const DATA = '';
export function decodeEarth() {
  const bin = atob(DATA), n = MAP_W * MAP_H;
  const cls = new Uint8Array(n), shade = new Int8Array(n);
  let p = 0, i = 0;
  while (i < n && p < bin.length) {
    let tok = 0, mul = 1, b;
    do { b = bin.charCodeAt(p++); tok += (b & 127) * mul; mul *= 128; } while (b & 128);
    const v = tok % 80, run = Math.floor(tok / 80) + 1, c = v >> 4, s = (v & 15) - 8;
    for (let k = 0; k < run && i < n; k++, i++) { cls[i] = c; shade[i] = s; }
  }
  return { cls, shade };
}
